const SESSION_SCHEMA = 'stellar-forge.seller-usage-session.v1';
const REPORT_SCHEMA = 'stellar-forge.seller-usage-history.v1';
const COVERAGE_FORMAT = 'stellar-forge.seller-usage-day-routes.v1';
