    '\n), sf30_budget AS MATERIALIZED (\nSELECT sf30_page.*, (' + bytes + ') > ' +
    query.maxBytes + ' AS "' + flag + '" FROM sf30_page\n)\nSELECT ' +
    names.map(name => 'CASE WHEN "' + flag + '" THEN NULL ELSE ' + name + ' END AS ' + name).join(', ') +
