  "pg_catalog.pg_get_function_identity_arguments(p.oid) AS identity_arguments,",
  "pg_catalog.pg_get_function_arguments(p.oid) AS arguments,",
  "pg_catalog.pg_get_function_result(p.oid) AS result",
